import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('JSX Basics', () => {
  test('Renders an <h1> with "Hello, React!"', async () => {
    const { container: root } = render(<App />);
    const h1 = root.querySelector('h1');
if (!h1) throw new Error('No <h1> element found');
if (!h1.textContent.includes('Hello, React!'))
  throw new Error('h1 should contain "Hello, React!"');
  });

  test('Displays the year 2026 in a <p> tag', async () => {
    const { container: root } = render(<App />);
    const paragraphs = root.querySelectorAll('p');
const hasYear = Array.from(paragraphs).some(p => p.textContent.includes('2026'));
if (!hasYear) throw new Error('A <p> should contain "2026"');
  });

  test('Has a <p> with className="subtitle"', async () => {
    const { container: root } = render(<App />);
    const el = root.querySelector('.subtitle');
if (!el) throw new Error('No element with className "subtitle" found');
if (el.tagName !== 'P') throw new Error('The element with class "subtitle" should be a <p>');
  });

  test('Wrapped in a single root <div>', async () => {
    const { container: root } = render(<App />);
    const wrapper = root.firstElementChild;
if (!wrapper || wrapper.tagName !== 'DIV')
  throw new Error('Component should return a single <div> wrapper');
  });
});
